/*
 * prog44_miller_rabin.c
 *
 * Re‑implementation of the original binary’s functionality.
 * The program reads a single command‑line argument, interprets it as a
 * decimal integer and reports its primality using a deterministic
 * Miller‑Rabin test for 32‑bit numbers.
 *
 * Output strings (exactly as in the original binary):
 *   NO_INPUT      – no argument supplied
 *   BAD_INPUT     – argument is not a valid integer (or contains extra chars)
 *   OUT_OF_RANGE  – integer > 0xBFA17DC6 (≈3.2·10⁹)
 *   PRIME         – the number is prime
 *   NOT_PRIME     – the number is composite (including 0, 1, and negatives)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

/* Upper bound used by the original program (0xBFA17DC6) */
#define MAX_VALUE 0xBFA17DC6ULL

/* Deterministic Miller‑Rabin bases for 32‑bit integers */
static const uint32_t bases[] = {2, 3, 5, 7, 11, 13};
static const size_t n_bases = sizeof(bases) / sizeof(bases[0]);

/* (a * b) % mod – safe for 64‑bit intermediate values */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    return (a * b) % mod;
}

/* (base ^ exp) % mod – binary exponentiation */
static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* Miller‑Rabin test for a single base */
static int miller_rabin_witness(uint32_t n, uint32_t a)
{
    /* write n‑1 as d * 2^s with d odd */
    uint32_t d = n - 1;
    uint32_t s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    uint64_t x = pow_mod(a, d, n);
    if (x == 1 || x == n - 1)
        return 0;               /* probably prime for this base */

    for (uint32_t r = 1; r < s; ++r) {
        x = mul_mod(x, x, n);
        if (x == n - 1)
            return 0;           /* probably prime for this base */
    }
    return 1;                   /* definitely composite */
}

/* Deterministic Miller‑Rabin for 32‑bit unsigned integers */
static int is_prime_uint32(uint32_t n)
{
    if (n < 2)
        return 0;

    /* Small‑prime shortcuts (also catches n == base) */
    for (size_t i = 0; i < n_bases; ++i) {
        if (n == bases[i])
            return 1;
        if (n % bases[i] == 0)
            return 0;
    }

    for (size_t i = 0; i < n_bases; ++i) {
        if (miller_rabin_witness(n, bases[i]))
            return 0;           /* composite */
    }
    return 1;                   /* prime */
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long val = strtoll(argv[1], &endptr, 10);

    /* Ensure the whole argument was consumed */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (val < 0) {
        puts("NOT_PRIME");
        return 0;
    }

    uint64_t n = (uint64_t)val;

    if (n > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (is_prime_uint32((uint32_t)n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
